                criticality = np.clip((distance_matrix[i, j] - median_distance) / (neighbors[1] - median_distance + 1e-10), 0.5, None)
                normalized_distance = neighbors[0] / (distance_matrix[i, j] + 1e-10)
                guide_matrix[i, j] = distance_matrix[i, j] * (1 + criticality) * (0.9 + 0.1 * normalized_distance)
    return guide_matrix

import numpy as np

def generate_guide_matrix(distance_matrix: np.ndarray) -> np.ndarray:
    n = distance_matrix.shape[0]
    guide_matrix = np.zeros((n, n))
    for i in range(n):
        avg_distance = np.mean(distance_matrix[i][distance_matrix[i] != 0])
        for j in range(n):
            if i != j:
                penalty = (distance_matrix[i, j] - avg_distance) / (avg_distance + 1e-10)
                guide_matrix[i, j] = distance_matrix[i, j] * (1 + 0.5 * max(0, penalty))
    return guide_matrix
